let fn=0,step=0,timer;const $=id=>document.getElementById(id);function render(){const d=tourData[fn];$('tourTitle').innerHTML=d.title;$('tourStepTitle').textContent=d.step;$('tourDescription').textContent=d.desc;$('tourBullets').innerHTML=d.bullets.map(x=>'<li>'+x+'</li>').join('');$('tourUiTitle').textContent=d.ui;$('tourCounter').textContent=(step+1)+' / '+d.slides.length;$('tourContent').innerHTML=d.slides[step];document.querySelectorAll('.tour-sidebar button').forEach((b,i)=>b.classList.toggle('active',i===fn));$('tourDots').innerHTML=d.slides.map((_,i)=>'<button class="'+(i===step?'active':'')+'" data-step="'+i+'"></button>').join('');document.querySelectorAll('#tourDots button').forEach(b=>b.onclick=()=>{step=+b.dataset.step;render();restart()});}function next(){step++;if(step>=tourData[fn].slides.length){fn=(fn+1)%tourData.length;step=0}render()}function prev(){step--;if(step<0){fn=(fn-1+tourData.length)%tourData.length;step=tourData[fn].slides.length-1}render()}function restart(){clearInterval(timer);timer=setInterval(next,5200)}$('tourNext').onclick=()=>{next();restart()};$('tourPrev').onclick=()=>{prev();restart()};document.querySelectorAll('.tour-sidebar button').forEach(b=>b.onclick=()=>{fn=+b.dataset.fn;step=0;render();restart()});document.querySelector('.tour-frame').addEventListener('mouseenter',()=>clearInterval(timer));document.querySelector('.tour-frame').addEventListener('mouseleave',restart);render();restart();

// Fixed landing-page demo audio. The text, language and voice are intentionally static.
(function(){
  var audio=$('ttsDemoAudio'),btn=$('ttsDemoPlay'),bar=$('ttsDemoProgress'),time=$('ttsDemoTime'),player=$('ttsDemoPlayer');
  if(!audio||!btn||!bar||!time)return;
  var fallback=false, speaking=false, duration=4;
  function fmt(s){s=Math.max(0,Math.floor(Number(s)||0));return Math.floor(s/60)+':'+String(s%60).padStart(2,'0');}
  function resetUI(){bar.style.width='0%';time.textContent='0:00 / '+fmt(audio.duration||duration);btn.textContent='▶ Nghe thử';player.classList.remove('is-playing');}
  audio.addEventListener('loadedmetadata',function(){duration=audio.duration||4;resetUI();});
  audio.addEventListener('timeupdate',function(){var d=audio.duration||duration;bar.style.width=Math.min(100,(audio.currentTime/d)*100)+'%';time.textContent=fmt(audio.currentTime)+' / '+fmt(d);});
  audio.addEventListener('play',function(){btn.textContent='❚❚ Tạm dừng';player.classList.add('is-playing');});
  audio.addEventListener('pause',function(){if(!speaking)resetUI();});
  audio.addEventListener('ended',resetUI);
  audio.addEventListener('error',function(){fallback=true;});
  btn.addEventListener('click',function(){
    if(fallback){
      if(!('speechSynthesis' in window)){return;}
      if(speaking){speechSynthesis.cancel();speaking=false;resetUI();return;}
      var u=new SpeechSynthesisUtterance('Xin chào, đây là giọng đọc thử của VideoDubing AI.');u.lang='vi-VN';u.rate=0.95;u.pitch=1;
      u.onstart=function(){speaking=true;btn.textContent='❚❚ Tạm dừng';player.classList.add('is-playing');};
      u.onend=function(){speaking=false;resetUI();};
      u.onerror=function(){speaking=false;resetUI();};
      speechSynthesis.cancel();speechSynthesis.speak(u);
      return;
    }
    if(audio.paused){audio.play().catch(function(){fallback=true;btn.click();});}else{audio.pause();}
  });
  resetUI();
})();
</script></body></html>